"""Fill the auto-generated results block of README.md from results/summary.md."""

from __future__ import annotations

import json
import re
from pathlib import Path

START = (
    "<!-- BENCHMARK-RESULTS:START "
    "(auto-generated by scripts/update_readme_results.py; do not edit by hand) -->"
)
END = "<!-- BENCHMARK-RESULTS:END -->"
NO_RESULTS = (
    "**No results generated yet.** Run `make bench-fast` (smoke test) or `make bench` (full benchmark); "
    "the harness writes `results/summary.md` and this block is regenerated from it automatically."
)


def _has_measurements(results_json: Path) -> bool:
    if not results_json.exists():
        return False
    try:
        with open(results_json, encoding="utf-8") as fh:
            data = json.load(fh)
    except (OSError, ValueError):
        return False
    return any(r.get("status") == "ok" for r in data.get("runs", []))


def render_block(summary_md: Path, results_json: Path) -> str:
    """Markdown to place between the markers (summary with README-relative links)."""
    if not summary_md.exists() or not _has_measurements(results_json):
        return NO_RESULTS
    text = summary_md.read_text(encoding="utf-8")
    text = text.replace("](plots/", "](results/plots/")
    # demote headings so the generated block nests under the README's Results section
    text = re.sub(r"^(#{1,4}) ", lambda m: "#" * (len(m.group(1)) + 2) + " ", text, flags=re.MULTILINE)
    return text.strip()


def update_readme(readme: Path, summary_md: Path, results_json: Path) -> bool:
    """Replace the marked block; returns True if README changed.

    Raises:
        ValueError: if the markers are missing from README.md.
    """
    content = readme.read_text(encoding="utf-8")
    if START not in content or END not in content:
        raise ValueError(f"{readme} has no auto-generated results markers")
    head, rest = content.split(START, 1)
    _, tail = rest.split(END, 1)
    new = f"{head}{START}\n{render_block(summary_md, results_json)}\n{END}{tail}"
    if new != content:
        readme.write_text(new, encoding="utf-8")
        return True
    return False
